WFJ.Data.add("book", {
  ["47101623c9f7dcac"] = { "Data dell'annotazione: sconosciuta\n\nNome: Nathanos Marris, umano, Signore dei ranger di Lordaeron.\n\nAnnotazione:\n\nPrendo atto del dissenso di Kael'thas Sunstrider riguardo alla mia decisione di ammettere Nathanos Marris nell'ordine. Si prenda atto anche che Nathanos, pur essendo umano, è uno dei ranger più dotati che io abbia mai avuto il piacere di addestrare.\n\n(continua)", "." },
  ["471b8e8f9fbe4cbe"] = { "[Le parole qui sotto sono state scarabocchiate in fretta sul retro dell'atto]\n\nAbbiamo fatto pressione su Furlbrow e ci siamo presi il suo atto. Ho pensato che potesse tornarti utile, se vuoi falsificarne uno per un posto tuo. I Furlbrow non ci daranno fastidio. L'ultima volta che li ho visti se ne stavano andando dalle ⟦Westfall=Marche Occidentali⟧, bloccati con un carro rotto.", "." },
  ["472c6f4bf0358580"] = { "⟦Goblin Engineering=Ingegneria dei Goblin⟧\n\nEssendo una razza che si ritrova neutrale in quasi ogni conflitto, i goblin si sono dati molto da fare per trasformare la scienza in profitto. Abbracciano le applicazioni pratiche dell'ingegneria, come dimostrano i loro progetti radicali di esplosivi, armi da fuoco e macchinari. L'ingegneria goblin nutre solo un interesse passeggero per la teoria; le loro invenzioni di solito non hanno il problema di non funzionare, ma piuttosto di funzionare troppo bene. Di certo non è per i deboli di cuore.", "." },
  ["478778849257f2e9"] = { "Gli eredar, un'insidiosa razza di stregoni diabolici, usarono la loro magia da stregone per invadere e ridurre in schiavitù numerosi mondi. Le razze native di quei mondi furono mutate dai poteri malevoli degli eredar e trasformate esse stesse in demoni.", "." },
  ["47a5b388c85d4171"] = { "Recuperato dalle rovine sommerse di Suramar, questo astrolabio funzionante fu costruito dagli elfi della notte Alti Nobili quasi dodicimila anni fa. Gli Alti Nobili, ossessionati dalla magia, dall'occulto e dall'astronomia, svilupparono una serie di ingegnosi apparecchi. Questo congegno offre informazioni preziose sul livello di conoscenza scientifica degli antichi elfi della notte.", "." },
})
